function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 2 || grid.length > 100) return 'grid needs 2 to 100 rows.';
  const n = grid[0].length;
  if (n < 2 || n > 100) return 'Each row needs 2 to 100 cells.';
  if (grid.some(row => row.length !== n)) return 'All rows must have the same length.';
  if (grid.some(row => row.some(v => v !== 0 && v !== 1))) return 'Every cell is 0 or 1.';
  return null;
}

