function isThereAPath(grid) {
  const m = grid.length, n = grid[0].length;
  const walk = (r, c, balance) => {
    const next = balance + (grid[r][c] === 1 ? 1 : -1);
    if (r === m - 1 && c === n - 1) return next === 0;
    if (r + 1 < m && walk(r + 1, c, next)) return true;
    if (c + 1 < n && walk(r, c + 1, next)) return true;
    return false;
  };
  return walk(0, 0, 0);
}

