function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let m, n;
  if (size === 'large') {
    m = int(60, 100);
    n = int(60, 100);
    // Mostly even path lengths, so the answer is not decided by parity alone.
    if (rand() < 0.85 && (m + n) % 2 === 0) n = n === 100 ? 99 : n + 1;
  } else {
    m = int(2, 6);
    n = int(2, 6);
    if (rand() < 0.75 && (m + n) % 2 === 0) n = n === 6 ? 5 : n + 1;
  }
  const ones = 0.15 + rand() * 0.7;
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < ones ? 1 : 0)));
  return [grid];
}
